1	//! Step execution engine.
2	//!
3	//! Executes resolved steps with proper environment handling,
4	//! interpolation, and hook execution.
5	
6	use crate::checks::CheckResult;
7	use crate::config::interpolation::{resolve_string, InterpolationContext};
8	use crate::error::{BivvyError, Result};
9	use crate::shell::{execute, execute_streaming, CommandOptions, OutputCallback};
10	use crate::steps::resolved::ResolvedStep;
11	use std::collections::HashMap;
12	use std::path::Path;
13	use std::time::Duration;
14	
15	/// Status of a step in the workflow.
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub enum StepStatus {
18	    /// Step is waiting to run.
19	    Pending,
20	
21	    /// Step is currently executing.
22	    Running,
23	
24	    /// Step completed successfully.
25	    Completed,
26	
27	    /// Step failed.
28	    Failed,
29	
30	    /// Step was skipped (already complete or dependency failed).
31	    Skipped,
32	}
33	
34	impl StepStatus {
35	    /// Check if this is a terminal state (no more changes expected).
36	    pub fn is_terminal(&self) -> bool {
37	        matches!(
38	            self,
39	            StepStatus::Completed | StepStatus::Failed | StepStatus::Skipped
40	        )
41	    }
42	
43	    /// Get a display character for this status.
44	    pub fn display_char(&self) -> char {
45	        match self {
46	            StepStatus::Pending => '○',
47	            StepStatus::Running => '◉',
48	            StepStatus::Completed => '✓',
49	            StepStatus::Failed => '✗',
50	            StepStatus::Skipped => '⊘',
51	        }
52	    }
53	
54	    /// Title-case label shown in the run-path step result line.
55	    ///
56	    /// This is the single source of truth for what appears next to
57	    /// `display_char()` on the post-spinner result row, e.g. the
58	    /// `Completed` in `      ✓ Completed (43ms)`.
59	    pub fn label(&self) -> &'static str {
60	        match self {
61	            StepStatus::Pending => "Pending",
62	            StepStatus::Running => "Running",
63	            StepStatus::Completed => "Completed",
64	            StepStatus::Failed => "Failed",
65	            StepStatus::Skipped => "Skipped",
66	        }
67	    }
68	}
69	
70	impl std::fmt::Display for StepStatus {
71	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
72	        let s = match self {
73	            StepStatus::Pending => "pending",
74	            StepStatus::Running => "running",
75	            StepStatus::Completed => "completed",
76	            StepStatus::Failed => "failed",
77	            StepStatus::Skipped => "skipped",
78	        };
79	        write!(f, "{}", s)
80	    }
81	}
82	
83	/// Result of executing a step.
84	#[derive(Debug)]
85	pub struct StepResult {
86	    /// Step name.
87	    pub name: String,
88	
89	    /// Whether the step succeeded.
90	    pub success: bool,
91	
92	    /// Execution duration.
93	    pub duration: Duration,
94	
95	    /// Exit code (if command was run).
96	    pub exit_code: Option<i32>,
97	
98	    /// Whether step was skipped (already complete).
99	    pub skipped: bool,
100	
101	    /// Completion check result (if run).
102	    pub check_result: Option<CheckResult>,
103	
104	    /// Error message (if failed).
105	    pub error: Option<String>,
106	
107	    /// Captured output (if available).
108	    pub output: Option<String>,
109	
110	    /// Recovery detail (e.g., "succeeded on retry (attempt 2)", "skipped by user").
111	    pub recovery_detail: Option<String>,
112	}
113	
114	impl StepResult {
115	    /// Create a skipped result (user actively declined to run this step).
116	    pub fn skipped(name: &str, check_result: CheckResult) -> Self {
117	        Self {
118	            name: name.to_string(),
119	            success: true,
120	            duration: Duration::ZERO,
121	            exit_code: None,
122	            skipped: true,
123	            check_result: Some(check_result),
124	            error: None,
125	            output: None,
126	            recovery_detail: None,
127	        }
128	    }
129	
130	    /// Create a check-passed result (check passed, step didn't need to run).
131	    ///
132	    /// Unlike `skipped`, this records as a successful completion — dependents
133	    /// should proceed, and the summary shows ✓ instead of ○.
134	    pub fn check_passed(name: &str, check_result: CheckResult) -> Self {
135	        Self {
136	            name: name.to_string(),
137	            success: true,
138	            duration: Duration::ZERO,
139	            exit_code: None,
140	            skipped: false,
141	            check_result: Some(check_result),
142	            error: None,
143	            output: None,
144	            recovery_detail: None,
145	        }
146	    }
147	
148	    /// Create a success result.
149	    pub fn success(
150	        name: &str,
151	        duration: Duration,
152	        exit_code: Option<i32>,
153	        output: Option<String>,
154	    ) -> Self {
155	        Self {
156	            name: name.to_string(),
157	            success: true,
158	            duration,
159	            exit_code,
160	            skipped: false,
161	            check_result: None,
162	            error: None,
163	            output,
164	            recovery_detail: None,
165	        }
166	    }
167	
168	    /// Create a failure result.
169	    pub fn failure(name: &str, duration: Duration, error: String, output: Option<String>) -> Self {
170	        Self {
171	            name: name.to_string(),
172	            success: false,
173	            duration,
174	            exit_code: None,
175	            skipped: false,
176	            check_result: None,
177	            error: Some(error),
178	            output,
179	            recovery_detail: None,
180	        }
181	    }
182	
183	    /// Get the status of this result.
184	    pub fn status(&self) -> StepStatus {
185	        if self.skipped {
186	            StepStatus::Skipped
187	        } else if self.success {
188	            StepStatus::Completed
189	        } else {
190	            StepStatus::Failed
191	        }
192	    }
193	
194	    /// Whether this result represents a step whose check passed without
195	    /// actually executing the command (the work was already done).
196	    pub fn was_check_passed(&self) -> bool {
197	        self.success && !self.skipped && self.check_result.is_some() && self.duration.is_zero()
198	    }
199	
200	    /// Whether the step's command actually executed (succeeded or failed),
201	    /// as opposed to being skipped or short-circuited by a passing check.
202	    pub fn actually_executed(&self) -> bool {
203	        !self.skipped && !self.was_check_passed()
204	    }
205	
206	    /// Generate a summary line for display.
207	    pub fn summary_line(&self) -> String {
208	        let status = self.status();
209	        let duration_str = format_duration(self.duration);
210	
211	        match status {
212	            StepStatus::Completed => {
213	                format!("{} {} ({})", status.display_char(), self.name, duration_str)
214	            }
215	            StepStatus::Skipped => {
216	                let reason = self
217	                    .check_result
218	                    .as_ref()
219	                    .map(|c| c.description.as_str())
220	                    .unwrap_or("already complete");
221	                format!("{} {} ({})", status.display_char(), self.name, reason)
222	            }
223	            StepStatus::Failed => {
224	                let error = self.error.as_deref().unwrap_or("unknown error");
225	                format!("{} {} - {}", status.display_char(), self.name, error)
226	            }
227	            _ => format!("{} {}", status.display_char(), self.name),
228	        }
229	    }
230	}
231	
232	fn format_duration(duration: Duration) -> String {
233	    let secs = duration.as_secs();
234	    let millis = duration.subsec_millis();
235	
236	    if secs == 0 {
237	        format!("{}ms", millis)
238	    } else if secs < 60 {
239	        format!("{}.{}s", secs, millis / 100)
240	    } else {
241	        let mins = secs / 60;
242	        let secs = secs % 60;
243	        format!("{}m {}s", mins, secs)
244	    }
245	}
246	
247	/// Options for step execution.
248	#[derive(Debug, Clone, Default)]
249	pub struct ExecutionOptions {
250	    /// Force run even if completed.
251	    pub force: bool,
252	
253	    /// Dry run mode (don't actually execute).
