263	/// Build the merged environment a step will run with.
264	///
265	/// Layers are applied lowest → highest:
266	///
267	/// 1. `base_env` — pre-merged YAML layers (settings.env_vars + workflow.env)
268	/// 2. step `env_file` — loaded from disk if `step.env_vars.env_file` is set
269	/// 3. step `env` — inline `env:` map on the step
270	/// 4. `process_env` — the parent process environment
271	///
272	/// The parent process env wins last so that shell-exported variables
273	/// (`DATABASE_URL=... bivvy run`) override values declared in YAML.
274	///
275	/// # Errors
276	///
277	/// Returns an error if `step.env_vars.env_file` is set, the file is missing,
278	/// and `env_file_optional` is false.
279	pub fn build_step_env(
280	    step: &ResolvedStep,
281	    project_root: &Path,
282	    base_env: &HashMap<String, String>,
283	    process_env: &HashMap<String, String>,
284	) -> Result<HashMap<String, String>> {
285	    let mut env = base_env.clone();
286	
287	    if let Some(ref env_file_path) = step.env_vars.env_file {
288	        let resolved_path = project_root.join(env_file_path);
289	        if step.env_vars.env_file_optional {
290	            let file_env = crate::config::load_env_file_optional(&resolved_path);
291	            env.extend(file_env);
292	        } else {
293	            let file_env = crate::config::load_env_file(&resolved_path)?;
294	            env.extend(file_env);
295	        }
296	    }
297	
298	    env.extend(
299	        step.env_vars
300	            .env
301	            .iter()
302	            .map(|(k, v)| (k.clone(), v.clone())),
303	    );
304	
305	    env.extend(process_env.iter().map(|(k, v)| (k.clone(), v.clone())));
306	
307	    Ok(env)
308	}
