310	/// Execute a single step.
311	///
312	/// See [`build_step_env`] for the env-layering precedence.
313	pub fn execute_step(
314	    step: &ResolvedStep,
315	    project_root: &Path,
316	    context: &InterpolationContext,
317	    base_env: &HashMap<String, String>,
318	    process_env: &HashMap<String, String>,
319	    options: &ExecutionOptions,
320	    output_callback: Option<OutputCallback>,
321	) -> Result<StepResult> {
322	    // Create step-scoped context with template inputs
323	    let context = &context.with_step_inputs(&step.inputs);
324	
325	    // Note: Check evaluation and precondition evaluation
326	    // are handled by the orchestrator BEFORE calling execute_step().
327	    // The executor only executes — it does not make run/skip decisions.
328	
329	    let env = build_step_env(step, project_root, base_env, process_env)?;
330	
331	    // Make the resolved env available for ${VAR} interpolation in
332	    // command/hook strings.
333	    let mut ctx_with_env = context.clone();
334	    ctx_with_env.env = env.clone();
335	    let context = &ctx_with_env;
336	
337	    // Dry run mode
338	    if options.dry_run {
339	        let display = if step.behavior.sensitive {
340	            "Would run: [SENSITIVE]".to_string()
341	        } else {
342	            let command = resolve_string(&step.execution.command, context)?;
343	            format!("Would run: {}", command)
344	        };
345	        return Ok(StepResult::success(
346	            &step.name,
347	            Duration::ZERO,
348	            None,
349	            Some(display),
350	        ));
351	    }
352	
353	    // Resolve command with interpolation
354	    let command = resolve_string(&step.execution.command, context)?;
355	
356	    // Guard against empty commands
357	    if command.trim().is_empty() {
358	        return Err(BivvyError::StepExecutionError {
359	            step: step.name.clone(),
360	            message: "step has no command to execute (command is empty)".to_string(),
361	        });
362	    }
363	
364	    // Execute before hooks
365	    for hook in &step.hooks.before {
366	        let hook_cmd = resolve_string(hook, context)?;
367	        execute_hook(&hook_cmd, project_root, &env)?;
368	    }
369	
370	    // Execute main command
371	    let cmd_options = CommandOptions {
372	        cwd: Some(project_root.to_path_buf()),
373	        env: env.clone(),
374	        capture_stdout: options.capture_output || output_callback.is_none(),
375	        capture_stderr: options.capture_output || output_callback.is_none(),
376	        stdin_null: true,
377	        ..Default::default()
378	    };
379	
380	    let result = if let Some(callback) = output_callback {
381	        execute_streaming(&command, &cmd_options, callback)?
382	    } else {
383	        execute(&command, &cmd_options)?
384	    };
385	
386	    if !result.success {
387	        return Ok(StepResult::failure(
388	            &step.name,
389	            result.duration,
390	            format!("Command failed with exit code {:?}", result.exit_code),
391	            Some(result.stderr),
392	        ));
393	    }
394	
395	    // Execute after hooks
396	    for hook in &step.hooks.after {
397	        let hook_cmd = resolve_string(hook, context)?;
398	        execute_hook(&hook_cmd, project_root, &env)?;
399	    }
400	
401	    Ok(StepResult::success(
402	        &step.name,
403	        result.duration,
404	        result.exit_code,
405	        if options.capture_output {
406	            Some(result.stdout)
407	        } else {
408	            None
409	        },
410	    ))
411	}
412	
413	fn execute_hook(command: &str, cwd: &Path, env: &HashMap<String, String>) -> Result<()> {
414	    let options = CommandOptions {
415	        cwd: Some(cwd.to_path_buf()),
416	        env: env.clone(),
417	        capture_stdout: true,
418	        capture_stderr: true,
419	        ..Default::default()
420	    };
421	
422	    let result = execute(command, &options)?;
423	
424	    if !result.success {
425	        return Err(BivvyError::StepExecutionError {
426	            step: "hook".to_string(),
427	            message: format!("Hook '{}' failed: {}", command, result.stderr),
428	        });
429	    }
430	
431	    Ok(())
432	}
