            error: exec_result.result.error.clone(),
        });
        event_bus.emit(&BivvyEvent::StepOutcome {
            name: self.step_name.to_string(),
            outcome: StepOutcomeKind::Failed,
            detail: exec_result.result.error.clone(),
            duration_ms: Some(duration_ms),
        });
    }
    StepStatus::Skipped => {
